def read(p):
    return pd.read_csv(p) if p.exists() else None


def summary():
    rows = []
    cmp = C.RES / "compare"
    for sp in ("test", "val"):
        M = read(cmp / f"{sp}_metrics.csv")
        S = read(cmp / f"{sp}_seed_spread.csv")
        if M is None: continue
        g = M.groupby(["model", "featureset"]).agg(n=("n", "first"), seeds=("seed", "size"), accuracy=("accuracy", "mean"), acc_lo=("acc_lo", "mean"),
                                                   acc_hi=("acc_hi", "mean"), macro_f1=("macro_f1", "mean"), macro_precision=("macro_precision", "mean"), macro_recall=("macro_recall", "mean"), f1_lo=("f1_lo", "mean"), f1_hi=("f1_hi", "mean")).reset_index()
        g.insert(0, "split", sp)
        if S is not None:
            g = g.merge(S[["model", "featureset", "acc_sd", "f1_sd"]], on=["model", "featureset"], how="left")
        rows.append(g)
    vr = read(C.RES / "baselines" / "val_results.csv")
    if not rows and vr is not None:           # no comparison yet: fall back to tuning-time validation results
        rows.append(vr.assign(split="val_tuning")[["split", "model", "featureset", "val_accuracy", "val_macro_f1", "val_macro_precision", "val_macro_recall"]].rename(
            columns={"val_accuracy": "accuracy", "val_macro_f1": "macro_f1", "val_macro_precision": "macro_precision", "val_macro_recall": "macro_recall"}))
    return pd.concat(rows, ignore_index=True) if rows else pd.DataFrame(columns=["split", "model", "featureset", "accuracy", "macro_f1", "macro_precision", "macro_recall"])


def figure(S):
    T = S[S.split == "test"] if (S.split == "test").any() else S
    if T.empty or "acc_lo" not in T:
        print("no comparison metrics yet; figure skipped")
        return
    T = T.sort_values("accuracy")
    lab = T.model + ":" + T.featureset
    fig, ax = plt.subplots(figsize=(7, 0.32 * len(T) + 1.5))
    ax.errorbar(T.accuracy, range(len(T)), xerr=[T.accuracy - T.acc_lo, T.acc_hi - T.accuracy], fmt="o", capsize=3)
    ax.set_yticks(range(len(T)), lab)
    ax.set(xlabel=f"Accuracy with 95% bootstrap interval (n={int(T.n.iloc[0])})", title="Model comparison")
    C.savefig(fig, "summary_comparison")


def learning_curve_figure(curves):
    """Train and validation loss per epoch, one line per run tag. Saved CSV only."""
    if curves is None or curves.empty:
        print("no learning curves yet; figure skipped")
        return
    fig, ax = plt.subplots(figsize=(7, 4))
    for i, (tag, d) in enumerate(curves.groupby("tag", sort=True)):
        d = d.sort_values("epoch")
        ax.plot(d.epoch, d.train_loss, color=f"C{i % 10}", ls="--", lw=1)
        ax.plot(d.epoch, d.val_loss, color=f"C{i % 10}", lw=1.4, label=str(tag))
    ax.set(xlabel="Epoch", ylabel="Loss", title="Learning curves (solid: validation, dashed: train)")
    if curves.tag.nunique() <= 12: ax.legend(fontsize=6, ncol=2)
    C.savefig(fig, "report_learning_curves")


def late_recall_figure(late):
    """Recall on late-lot grains per model, hold-out arms against models that saw part of the lot. A missing cell stays empty."""
    if late is None or late.empty:
        print("no late-lot recall yet; figure skipped")
        return
    models = sorted(late.model.unique())
    fig, ax = plt.subplots(figsize=(7, 0.35 * len(models) + 1.5))
    for j, (subset, mark) in enumerate([("late_all", "o"), ("late_test", "s")]):
        d = late[late.subset == subset].set_index("model").reindex(models)
        y = np.arange(len(models)) + (j - 0.5) * 0.25
        ok = d.recall.notna().to_numpy()
        ax.errorbar(d.recall[ok], y[ok], xerr=[(d.recall - d.ci_low)[ok], (d.ci_high - d.recall)[ok]], fmt=mark, capsize=2, label=subset)
    ax.set_yticks(range(len(models)), models, fontsize=7)
    ax.set(xlabel="Recall on late-lot grains with 95% interval", title="Late-lot recall")
    ax.legend(fontsize=7)
    C.savefig(fig, "report_late_lot_recall")


def disclosures():
    """The fixed rows, then one row for extra reads, counted from the ledger, and one for code changes, counted from the code lock, if they exist."""
    rows = list(DISCLOSURES)
    L = read(C.RES / LEDGER)
    if L is not None and len(L):
        rows.append(("extra read", f"{len(L)} extra read(s) logged; see the ledger for caller, time and reason", f"results/{LEDGER}"))
    lock = C.RES / CODE_LOCK
    cc = json.loads(lock.read_text()).get("changes", []) if lock.exists() else []
    if cc: rows.append(("code changed after lock", f"{len(cc)} logged code change(s) after the lock; see the lock file for time and reason", f"results/{CODE_LOCK}"))
    return pd.DataFrame(rows, columns=["item", "what", "evidence_file"])


